create table public.resources(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,uploaded_by uuid not null references public.profiles(id),title text not null,description text,file_path text not null,file_name text not null,mime_type text not null,size_bytes bigint not null check(size_bytes>0),created_at timestamptz not null default now());
create table public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,created_by uuid not null references public.profiles(id),title text not null,instructions text not null,max_marks numeric(6,2) not null check(max_marks>0),due_at timestamptz not null,allow_late boolean not null default false,attachment_path text,created_at timestamptz not null default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,text_answer text,file_path text,submitted_at timestamptz not null default now(),is_late boolean not null default false,marks_obtained numeric(6,2),feedback text,graded_by uuid references public.profiles(id),graded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,student_id));
create table public.quizzes(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,created_by uuid not null references public.profiles(id),title text not null,description text,time_limit_minutes int not null check(time_limit_minutes>0),opens_at timestamptz not null,closes_at timestamptz not null,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(closes_at>opens_at));
create table public.quiz_questions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,position int not null,type public.question_type not null,prompt text not null,options jsonb not null,marks numeric(5,2) not null default 1 check(marks>0),created_at timestamptz not null default now());
create table public.quiz_answers(question_id uuid primary key references public.quiz_questions(id) on delete cascade,correct_option_ids text[] not null,created_at timestamptz not null default now());
create table public.quiz_attempts(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,started_at timestamptz not null default now(),submitted_at timestamptz,answers jsonb not null default '{}',score numeric(6,2),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(quiz_id,student_id));
create table public.announcements(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,author_id uuid not null references public.profiles(id),title text not null,body text not null,is_pinned boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.announcement_reads(user_id uuid not null references public.profiles(id) on delete cascade,announcement_id uuid not null references public.announcements(id) on delete cascade,read_at timestamptz not null default now(),created_at timestamptz not null default now(),primary key(user_id,announcement_id));
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,entity text not null,entity_id uuid,at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.chat_messages(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.complaints(id uuid primary key default gen_random_uuid(),raised_by uuid not null references public.profiles(id),course_id uuid references public.courses(id),category text not null check(category in('academic','technical','facility','conduct','other')),subject text not null,description text not null,attachment_path text,status public.complaint_status not null default 'open',admin_response text,resolved_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index resources_course_created_idx on public.resources(course_id,created_at desc);create index assignments_course_due_idx on public.assignments(course_id,due_at);create index submissions_assignment_idx on public.submissions(assignment_id);create index quiz_attempts_quiz_idx on public.quiz_attempts(quiz_id);create index announcements_course_created_idx on public.announcements(course_id,created_at desc);create index chat_messages_course_created_idx on public.chat_messages(course_id,created_at desc);create index complaints_status_created_idx on public.complaints(status,created_at desc);
create trigger submissions_updated before update on public.submissions for each row execute function public.set_updated_at();create trigger quizzes_updated before update on public.quizzes for each row execute function public.set_updated_at();create trigger quiz_attempts_updated before update on public.quiz_attempts for each row execute function public.set_updated_at();create trigger announcements_updated before update on public.announcements for each row execute function public.set_updated_at();create trigger chat_messages_updated before update on public.chat_messages for each row execute function public.set_updated_at();create trigger complaints_updated before update on public.complaints for each row execute function public.set_updated_at();
create or replace function public.guard_student_submission_update() returns trigger language plpgsql security definer set search_path=public as $$begin if auth.uid()=old.student_id and not public.is_admin() and not exists(select 1 from assignments a where a.id=old.assignment_id and public.teaches(a.course_id)) then if new.assignment_id<>old.assignment_id or new.student_id<>old.student_id or new.marks_obtained is distinct from old.marks_obtained or new.feedback is distinct from old.feedback or new.graded_by is distinct from old.graded_by or new.graded_at is distinct from old.graded_at then raise exception 'Students cannot modify grading fields or reassign a submission';end if;end if;return new;end$$;
create trigger submissions_student_guard before update on public.submissions for each row execute function public.guard_student_submission_update();
create or replace function public.guard_quiz_attempt_update() returns trigger language plpgsql security definer set search_path=public as $$begin if auth.uid()=old.student_id and not public.is_admin() and not exists(select 1 from quizzes q where q.id=old.quiz_id and public.teaches(q.course_id)) then if new.quiz_id<>old.quiz_id or new.student_id<>old.student_id or new.started_at<>old.started_at or new.score is distinct from old.score or old.submitted_at is not null then raise exception 'Students cannot alter attempt ownership, score, or timer';end if;end if;return new;end$$;
create trigger quiz_attempt_student_guard before update on public.quiz_attempts for each row execute function public.guard_quiz_attempt_update();
create or replace function public.guard_chat_message_update() returns trigger language plpgsql security definer set search_path=public as $$begin if not public.is_admin() and not public.teaches(old.course_id) then if new.course_id<>old.course_id or new.sender_id<>old.sender_id or new.created_at<>old.created_at or new.body<>'' or new.deleted_at is null then raise exception 'Chat messages may only be soft-deleted';end if;end if;return new;end$$;
create trigger chat_messages_soft_delete_guard before update on public.chat_messages for each row execute function public.guard_chat_message_update();
alter table public.resources enable row level security;alter table public.assignments enable row level security;alter table public.submissions enable row level security;alter table public.quizzes enable row level security;alter table public.quiz_questions enable row level security;alter table public.quiz_answers enable row level security;alter table public.quiz_attempts enable row level security;alter table public.announcements enable row level security;alter table public.announcement_reads enable row level security;alter table public.audit_log enable row level security;alter table public.chat_messages enable row level security;alter table public.complaints enable row level security;
create policy resources_read_member on public.resources for select using(public.is_course_member(course_id));create policy resources_teacher_add on public.resources for insert with check(public.is_admin() or (uploaded_by=auth.uid() and public.teaches(course_id)));create policy resources_owner_or_admin_delete on public.resources for delete using(public.is_admin() or uploaded_by=auth.uid());
create policy assignments_read_member on public.assignments for select using(public.is_course_member(course_id));create policy assignments_teacher_write on public.assignments for all using(public.is_admin() or (created_by=auth.uid() and public.teaches(course_id))) with check(public.is_admin() or (created_by=auth.uid() and public.teaches(course_id)));
create policy submissions_read_own_or_teacher on public.submissions for select using(public.is_admin() or student_id=auth.uid() or exists(select 1 from assignments a where a.id=assignment_id and public.teaches(a.course_id)));create policy submissions_student_add on public.submissions for insert with check(student_id=auth.uid() and exists(select 1 from assignments a where a.id=assignment_id and public.is_enrolled(a.course_id)));create policy submissions_student_edit on public.submissions for update using(student_id=auth.uid() and exists(select 1 from assignments a where a.id=assignment_id and public.is_enrolled(a.course_id))) with check(student_id=auth.uid());create policy submissions_teacher_grade on public.submissions for update using(public.is_admin() or exists(select 1 from assignments a where a.id=assignment_id and public.teaches(a.course_id))) with check(public.is_admin() or graded_by=auth.uid());
create policy quizzes_read_member on public.quizzes for select using(public.is_admin() or public.teaches(course_id) or (public.is_enrolled(course_id) and is_published));create policy quizzes_teacher_write on public.quizzes for all using(public.is_admin() or (created_by=auth.uid() and public.teaches(course_id))) with check(public.is_admin() or (created_by=auth.uid() and public.teaches(course_id)));
create policy quiz_questions_member on public.quiz_questions for select using(exists(select 1 from quizzes q where q.id=quiz_id and (public.is_admin() or public.teaches(q.course_id) or (public.is_enrolled(q.course_id) and q.is_published))));create policy quiz_questions_teacher_write on public.quiz_questions for all using(exists(select 1 from quizzes q where q.id=quiz_id and (public.is_admin() or public.teaches(q.course_id)))) with check(exists(select 1 from quizzes q where q.id=quiz_id and (public.is_admin() or public.teaches(q.course_id))));
create policy quiz_answers_teacher_only on public.quiz_answers for all using(exists(select 1 from quiz_questions qq join quizzes q on q.id=qq.quiz_id where qq.id=question_id and (public.is_admin() or public.teaches(q.course_id)))) with check(exists(select 1 from quiz_questions qq join quizzes q on q.id=qq.quiz_id where qq.id=question_id and (public.is_admin() or public.teaches(q.course_id))));
create policy attempts_read_own_or_teacher on public.quiz_attempts for select using(public.is_admin() or student_id=auth.uid() or exists(select 1 from quizzes q where q.id=quiz_id and public.teaches(q.course_id)));create policy attempts_student_add on public.quiz_attempts for insert with check(student_id=auth.uid() and exists(select 1 from quizzes q where q.id=quiz_id and public.is_enrolled(q.course_id)));create policy attempts_student_submit on public.quiz_attempts for update using(student_id=auth.uid() and submitted_at is null) with check(student_id=auth.uid());
create policy announcements_read_scope on public.announcements for select using(public.is_admin() or course_id is null or public.is_course_member(course_id));create policy announcements_create on public.announcements for insert with check((public.is_admin() and (course_id is null or true)) or (author_id=auth.uid() and course_id is not null and public.teaches(course_id)));create policy announcements_author_update on public.announcements for update using(public.is_admin() or author_id=auth.uid()) with check(public.is_admin() or author_id=auth.uid());create policy announcements_author_delete on public.announcements for delete using(public.is_admin() or author_id=auth.uid());
create policy announcement_reads_self on public.announcement_reads for all using(public.is_admin() or user_id=auth.uid()) with check(user_id=auth.uid());create policy audit_admin_read on public.audit_log for select using(public.is_admin());create policy audit_insert_self on public.audit_log for insert with check(actor_id=auth.uid() or public.is_admin());
create policy chat_member_read on public.chat_messages for select using(public.is_course_member(course_id));create policy chat_member_send on public.chat_messages for insert with check(sender_id=auth.uid() and public.is_course_member(course_id));create policy chat_member_delete on public.chat_messages for update using(public.is_admin() or (sender_id=auth.uid() and created_at>now()-interval '5 minutes') or public.teaches(course_id)) with check(public.is_admin() or sender_id=auth.uid() or public.teaches(course_id));
create policy complaints_read_own_admin on public.complaints for select using(raised_by=auth.uid() or public.is_admin());create policy complaints_create_self on public.complaints for insert with check(raised_by=auth.uid() and (course_id is null or public.is_course_member(course_id)));create policy complaints_admin_update on public.complaints for update using(public.is_admin()) with check(public.is_admin());
create view public.v_student_marks with (security_invoker=true) as select s.student_id,a.course_id,'assignment'::text as kind,a.id as item_id,a.title,s.marks_obtained as obtained,a.max_marks as max,s.graded_at from public.submissions s join public.assignments a on a.id=s.assignment_id where s.graded_at is not null union all select qa.student_id,q.course_id,'quiz'::text,q.id,q.title,qa.score,(select coalesce(sum(qq.marks),0) from public.quiz_questions qq where qq.quiz_id=q.id),qa.submitted_at from public.quiz_attempts qa join public.quizzes q on q.id=qa.quiz_id where qa.submitted_at is not null and qa.score is not null;
create policy storage_private_buckets on storage.buckets for select using(id in('resources','submissions','complaint-attachments'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('resources','resources',false,26214400,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.presentationml.presentation','image/jpeg','image/png','image/gif','image/webp','application/zip','application/x-zip-compressed']),('submissions','submissions',false,31457280,null),('complaint-attachments','complaint-attachments',false,10485760,null) on conflict(id) do nothing;
create policy storage_read_course_files on storage.objects for select using(bucket_id in('resources','submissions','complaint-attachments') and (public.is_admin() or (bucket_id='resources' and public.is_course_member((storage.foldername(name))[1]::uuid))));
create policy storage_teacher_upload_resources on storage.objects for insert with check(bucket_id='resources' and (public.is_admin() or (public.teaches((storage.foldername(name))[1]::uuid) and (storage.foldername(name))[2] is not null)));
create policy storage_owner_delete on storage.objects for delete using(public.is_admin() or owner_id=auth.uid()::text);
